const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Plaquemines-Balize Delta region (Mississippi River Delta)
  const delta = ee.Geometry.Rectangle([-90.5, 28.8, -88.5, 29.6]);

  // Date range: January 21-24, 2025
  const startDate = '2025-01-21';
  const endDate = '2025-01-24';

  // Acquire Sentinel-2 collection
  let col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(delta)
    .filterDate(startDate, endDate)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));

  const colSize = await col.size().getInfo();
  console.log(`Images found (Jan 21-24, 2025): ${colSize}`);

  // Check for data availability
  if (colSize === 0) {
    console.log('No Sentinel-2 images found. Attempting Landsat 8/9...');
    col = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterBounds(delta)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUD_COVER', 80));
    const landSatSize = await col.size().getInfo();
    console.log(`Landsat images found: ${landSatSize}`);
    if (landSatSize === 0) {
      console.log('Empty Collection');
      console.log('C1');
      return;
    }
  }

  // Mosaic images (in case multiple exist)
  const img = col.median();

  // Calculate NDSI (Normalized Difference Snow Index)
  // For Sentinel-2: NDSI = (B3-B11)/(B3+B11), where B3=Green(560nm), B11=SWIR(1610nm)
  const ndsi = img.normalizedDifference(['B3', 'B11']).rename('NDSI');

  // Cloud mask using QA60
  const qa60 = img.select('QA60');
  const cloudBitMask = 1 << 10; // Cloud bit
  const cirrusBitMask = 1 << 11; // Cirrus bit
  const cloudMask = qa60.bitwiseAnd(cloudBitMask).eq(0)
    .and(qa60.bitwiseAnd(cirrusBitMask).eq(0));

  const ndsiMasked = ndsi.updateMask(cloudMask);

  // Count valid pixels with NDSI > 0.4 (snow threshold)
  const snowPixels = ndsiMasked.gt(0.4);
  const snowCount = snowPixels.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: delta,
    scale: 10,
    maxPixels: 1e9
  }).get('NDSI').getInfo();

  // Count total valid pixels
  const totalValid = ndsiMasked.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: delta,
    scale: 10,
    maxPixels: 1e9
  }).get('NDSI').getInfo();

  // Calculate mean NDSI
  const meanNDSI = ndsiMasked.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: delta,
    scale: 10,
    maxPixels: 1e9
  }).get('NDSI').getInfo();

  console.log(`Valid pixels: ${totalValid}, Snow pixels (NDSI>0.4): ${snowCount}`);
  console.log(`Mean NDSI: ${meanNDSI !== null ? meanNDSI.toFixed(3) : 'null'}`);

  // Validation and answer
  if (totalValid === null || totalValid === 0) {
    console.log('No valid pixels after cloud masking');
    console.log('C2');
    return;
  }

  if (meanNDSI === null || isNaN(meanNDSI)) {
    console.log('Calculation failed');
    console.log('C3');
    return;
  }

  if (snowCount !== null && snowCount > 0) {
    console.log('Snow detected in region');
    console.log('A');
  } else {
    console.log('No snow pixels detected');
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
